import MenuCard from "./MenuCard";

export default function MenuGrid({ menu, cart, addToCart, removeFromCart }) {
  if (!Array.isArray(menu)) {
    return <p>Loading menu...</p>;
  }

  return (
    <div className="menu-grid">
      {menu.map(item => {
        // rating / popularity (from backend)
        const isTopRated = item.avg_rating >= 4.5;
        const isPopular = item.sales_count >= 20;

        // quantity already in cart
        const cartItem = cart.find(i => i.id === item.id);
        const quantity = cartItem ? cartItem.quantity : 0;

        return (
          <div key={item.id} className="menu-card-wrapper">
            {(isTopRated || isPopular) && (
              <div className="menu-badges">
                {isPopular && (
                  <span className="badge badge-popular">🔥 Popular</span>
                )}
                {isTopRated && (
                  <span className="badge badge-rated">⭐ Top Rated</span>
                )}
              </div>
            )}

            <MenuCard
              item={item}
              quantity={quantity}
              addToCart={addToCart}
              removeFromCart={removeFromCart}
            />
          </div>
        );
      })}
    </div>
  );
}
